// Site content lives in /content as JSON and is edited through Decap CMS (/admin), which commits each save to
// GitHub; Netlify then rebuilds the site. Pages read it here at build time, so a save shows on the site after the
// rebuild (about 2 minutes). Field names must match public/admin/config.yml (generated by scripts/cms-config.mjs).
// Server components only: importing this module bundles every page's content. Client components use
// src/lib/settings.ts; blog posts are read in src/lib/blog.ts.
export { SETTINGS, whatsappLink, phoneHref, type Settings } from '@/lib/settings';
import homeJson from '../../content/home.json';
import projectsJson from '../../content/projects.json';
import platformsJson from '../../content/platforms.json';
import aboutJson from '../../content/about.json';
import contactJson from '../../content/contact.json';
import dmJson from '../../content/services/digital-marketing-seo.json';
import smmJson from '../../content/services/social-media-marketing.json';
import webJson from '../../content/services/web-development.json';
import ecomJson from '../../content/services/ecommerce-development.json';
import appJson from '../../content/services/mobile-app-development.json';
import brandJson from '../../content/services/branding-design.json';
import kochiJson from '../../content/locations/kochi.json';
import kozhikodeJson from '../../content/locations/kozhikode.json';
import trivandrumJson from '../../content/locations/trivandrum.json';

export type Seo = { title: string; description: string };
export type FaqItem = { q: string; a: string };
export type LinkItem = { label: string; href: string };
/** A card's picture: up to two icon keys from src/data/icons.json, or an uploaded image that replaces them */
export type IconFields = { icons?: string[]; image?: string };
export type Card = IconFields & { title: string; text: string; points?: string[] };

export type HomeContent = {
  seo: Seo;
  hero: { quote: string; quoteHighlight: string; quoteAuthor: string; heading: string; intro: string; primaryLabel: string; primaryHref: string; secondaryLabel: string; secondaryHref: string };
  projects: { eyebrow: string; title: string; linkLabel: string };
  services: { eyebrow: string; title: string; intro: string; items: (Card & { tagline: string; tags: string[]; link: string })[] };
  trust: { eyebrow: string; title: string; intro: string; items: Card[] };
  areas: { eyebrow: string; title: string; intro: string; items: { name: string; href: string; text: string }[] };
  faq: { eyebrow: string; title: string; items: FaqItem[] };
  cta: { badge: string; title: string; text: string; whatsappMessage: string };
};

export type Project = {
  id: string;
  category: 'retail' | 'healthcare' | 'realestate';
  icon: string;
  image?: string;
  sector: string;
  region: string;
  title: string;
  problem: string;
  journey: string[];
  featured?: boolean;
  results?: string[];
};
export type ProjectsContent = { seo: Seo; title: string; highlight: string; intro: string; items: Project[] };

export type PlatformItem = { name: string; logo: string; wordmark?: boolean };
export type PlatformsContent = { title: string; intro: string; groups: { title: string; items: PlatformItem[] }[] };

export type ServicePageContent = {
  seo: Seo;
  breadcrumb: string;
  schema: { name: string; serviceType: string; areaServed: string[] };
  hero: { eyebrow: string; title: string; highlight?: string; intro: string; primaryLabel: string; primaryHref: string; secondaryLabel?: string; secondaryHref?: string; whatsappMessage?: string };
  servicesSection: { title: string; intro?: string };
  services: Card[];
  highlight?: { title: string; paragraphs: string[]; points: string[] };
  stepsTitle?: string;
  steps: { title: string; text: string }[];
  related: LinkItem[];
  faqTitle: string;
  faqs: FaqItem[];
  contact?: { title: string; text: string };
};

export type LocationContent = {
  seo: Seo;
  slug: string;
  city: string;
  crumb: string;
  schemaAreas: string[];
  eyebrow: string;
  title: string;
  highlight: string;
  intro: string;
  whatsappMessage: string;
  marketTitle: string;
  market: string[];
  services: Card[];
  areas: string[];
  faqs: FaqItem[];
};

export type AboutContent = {
  seo: Seo;
  hero: { eyebrow: string; title: string; highlight: string; intro: string };
  story: { title: string; paragraphs: string[] };
  principles: { title: string; items: Card[] };
  areas: { title: string; intro: string; items: { name: string; href: string; text: string }[] };
  cta: { title: string; text: string };
};

export type ContactContent = { seo: Seo; title: string; highlight: string; intro: string };

export const HOME = homeJson as HomeContent;
export const PROJECTS = projectsJson as ProjectsContent;
export const PLATFORMS = platformsJson as PlatformsContent;
export const ABOUT = aboutJson as AboutContent;
export const CONTACT = contactJson as ContactContent;

export const SERVICE_PAGES = {
  'digital-marketing-seo': dmJson,
  'social-media-marketing': smmJson,
  'web-development': webJson,
  'ecommerce-development': ecomJson,
  'mobile-app-development': appJson,
  'branding-design': brandJson,
} as Record<string, ServicePageContent>;

export const LOCATIONS = {
  kochi: kochiJson,
  kozhikode: kozhikodeJson,
  trivandrum: trivandrumJson,
} as Record<string, LocationContent>;
